// One event, one letter, one consented agent or label the band chose from
// their own representation contacts — the consent, verification, do-not-
// contact, listing and monthly-allowance checks all happened upstream,
// inside the approval transaction. This executor either delivers exactly
// the letter that was approved or delivers nothing.
//
// It writes no words of its own. The introduction was composed in CrowdRelay
// at request time from the band's published listing and travels in `draft`;
// a payload without one is refused rather than filled in, because a letter
// this executor composed would be one the band never read — and the listing
// inside the payload is evidence the letter already cites, not material for
// a second letter.
const e = $json;
if (!e || e.type !== 'crowdrelay.representation.approach_requested' || e.version !== 1) {
  throw new Error('representation approach refused: unsupported event');
}
const d = e.data ?? {};
const actionId = String(d.action_id || '').trim();
const targetId = String(d.target_id || '').trim();
const draft = d.draft || {};
const subject = String(draft.subject || '').trim();
const body = String(draft.body || '').trim();
if (!actionId || !targetId) {
  throw new Error('representation approach refused: payload incomplete');
}
// The refusal that keeps the promise: no approved words, no send. An action
// queued before CrowdRelay composed letters carries no draft, and writing one
// here on the band's behalf is the exact thing this letter exists to prevent.
if (!subject || !body) {
  throw new Error(
    'representation approach refused: no approved letter in the payload — nothing may compose one here'
  );
}
// One contact, resolved inside the sending lock upstream. The address is
// never shown to the band — an approach can never be used to harvest it.
const email = String(d.contact_email || '').trim();
if (!email.includes('@')) {
  throw new Error('representation approach refused: target without contact_email');
}
return [{ json: {
  event_id: e.id,
  action_id: actionId,
  target_id: targetId,
  target_name: String(d.target_name || ''),
  target_kind: String(d.target_kind || ''),
  share_token: String(d.share_token || ''),
  SendTo: email,
  SendSubject: subject.slice(0, 220),
  SendBody: body,
}}];

const claim = $json;
const intent = $('Validate the approved approach').first().json;
// A replay of an already-finished action is a no-op, not an error.
if (claim.disposition === 'already_succeeded') return [];
// claimed is the only disposition that may reach the provider; in_flight
// and ambiguous stay claimed upstream and never send twice.
if (claim.disposition !== 'claimed' || !claim.claim_token) {
  throw new Error('Provider execution ' + (claim.disposition || 'unclaimed') + '; fail closed to prevent duplicate external side effects');
}
return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1) } }];

const intent = $('Fail-closed claim gate').first().json;
const failed = Boolean($json.error);
const ref = $json.threadId || $json.thread_id || $json.id || null;
return [{ json: {
  action_id: intent.action_id,
  receipt_key: 'representation_approach:' + intent.action_id + ':email',
  executor_id: $env.CROWDRELAY_EXECUTOR_ID || 'virya-n8n-primary',
  status: failed ? 'failed' : 'succeeded',
  claim_token: intent.claim_token,
  provider_reference: failed ? null : (ref ? String(ref).slice(0, 240) : null),
  error_kind: failed ? 'gmail_send_failed' : null,
  metadata: {
    channel: 'email',
    event_id: intent.event_id,
    target_id: intent.target_id,
    target_name: intent.target_name,
    target_kind: intent.target_kind,
  },
  occurred_at: new Date().toISOString(),
}}];
